        self.title("Canvas Grader")
        self.geometry("1000x900")
        self.minsize(820, 640)

        self.q = queue.Queue()
        self.busy = False
        self.stop_event = threading.Event()
        self.action_buttons = []

        self.assignment = None          # 현재 가져온 과제 (Canvas JSON)
        self.assignment_course = None   # 이 과제가 속한 course_id
        self.criteria = []
        self.sections_course = None     # section 정보가 속한 course_id
        self.user_sections = {}
        self.section_labels = []
